	/// <summary>
	///     Records the calls of 5-parameter methods, synthesized for arity 5 use sites.
	/// </summary>
	internal static class MethodRecords<T1, T2, T3, T4, T5>
	{
		public static void Append(global::Mockolate.Internals.MockInteractions owner, int memberId, string name, T1 parameter1, T2 parameter2, T3 parameter3, T4 parameter4, T5 parameter5)
		{
			Record r = new Record();
			r.MemberId = memberId;
			r.Name = name;
			r.P1 = parameter1;
			r.P2 = parameter2;
			r.P3 = parameter3;
			r.P4 = parameter4;
			r.P5 = parameter5;
			owner.Push(r);
		}

		private sealed class Record : global::Mockolate.Internals.RecordNode
		{
			public string Name = null!;
			public T1 P1 = default!;
			public T2 P2 = default!;
			public T3 P3 = default!;
			public T4 P4 = default!;
			public T5 P5 = default!;

			protected override global::Mockolate.Interactions.IInteraction CreateInteraction()
				=> new global::Mockolate.Interactions.MethodInvocation<T1, T2, T3, T4, T5>(Name, P1, P2, P3, P4, P5);
		}
	}
}

#nullable disable

